mapper.select:
with temp as ( SELECT DISTINCT PTL.CDATE CDATE, PTL.PORTFOLIO_ID, PTL.ACCT_ID ACCTID, PTL.CCY CCY, PTL.HODING_TYPE HODINGTYPE, PTLACCT.ACCT_TYPE ACCTTYPE, PP.PORTFOLIO_NAME PORTFOLIONAME, STL.ACCT_NAME ACCTNAME, FLOW.TRUSTEE_ID TRUSTEE_ID, PTL.AMOUNT, FLOW.AMOUNT1, FLOW.quotaIn, FLOW.quotaOut, '02' isSummary FROM PTL_CASH_POSITION PTL LEFT JOIN PTL_CAPACCT_INFO PTLACCT ON PTLACCT.PORTFOLIO_ID = PTL.PORTFOLIO_ID AND PTLACCT.ACCT_NO = PTL.ACCT_ID INNER JOIN STL_CAPACCT_INFO STL ON STL.ACCT_NO = PTL.ACCT_ID INNER JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = PTL.PORTFOLIO_ID LEFT JOIN (SELECT PTL.PORTFOLIO_ID, PTL.ACCT_ID, PTL.CDATE, PTL.CCY, PTL.HODING_TYPE, FP.TRUSTEE_ID, SUM(PTL.AMOUNT) AMOUNT1, SUM(case when PTL.AMOUNT >0 then PTL.AMOUNT else 0 end ) quotaIn, SUM(case when PTL.AMOUNT <0 then PTL.AMOUNT else 0 end ) quotaOut FROM PTL_CASH_POSITION_FLOW PTL LEFT JOIN PTL_CAPACCT_INFO PTLACCT ON PTLACCT.PORTFOLIO_ID = PTL.PORTFOLIO_ID AND PTLACCT.ACCT_NO = PTL.ACCT_ID LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = PTL.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
GROUP BY PTL.PORTFOLIO_ID, PTL.ACCT_ID, PTL.CDATE, PTL.CCY, PTL.HODING_TYPE, FP.TRUSTEE_ID ) FLOW ON PTL.PORTFOLIO_ID = FLOW.PORTFOLIO_ID AND PTL.ACCT_ID = FLOW.ACCT_ID AND PTL.CDATE = FLOW.CDATE AND PTL.CCY = FLOW.CCY AND PTL.HODING_TYPE = FLOW.HODING_TYPE LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
order by PTL.PORTFOLIO_ID,PTL.CDATE asc ) select * from ( select * from temp union select null CDATE, '' PORTFOLIO_ID, '' ACCTID, temp.ccy CCY, '' HODINGTYPE, '' ACCTTYPE, '' PORTFOLIONAME, '' ACCTNAME, '' TRUSTEE_ID, decode(SUM(AMOUNT),null,0,SUM(AMOUNT)) AMOUNT, decode(SUM(AMOUNT1),null,0,SUM(AMOUNT1)) AMOUNT1, decode(SUM(quotaIn),null,0,SUM(quotaIn)) quotaIn, decode(SUM(quotaOut),null,0,SUM(quotaOut)) quotaOut, '01' isSummary from temp group by ccy
)T1
T1.AMOUNT1 != 0
AND T1.TRUSTEE_ID = #{trusteeId}

sql.where:

	  PTL.HODING_TYPE = #{POSITION_TYPE_03}
	  AND FP.P_FINPROD_ID IS NULL

	  AND (( PTL.CHL_FINPROD_ID is null and EXISTS
			  (
				  SELECT
				  1
				  FROM
				  PTL_CAPACCT_INFO tpsp
				  WHERE
				  tpsp.PORTFOLIO_ID = PTL.PORTFOLIO_ID
				  AND tpsp.ACCT_NO= PTL.ACCT_ID )
			)
			  or PTL.CHL_FINPROD_ID is not null )


      and (PP.PORTFOLIO_ID in #{item})



		AND FIN_PRODUCT_ADD.PROD_MANAGER IN

			#{item}






		  AND PTL.CDATE BETWEEN #{startCDate}
		  AND #{endCDate}



      and PTLACCT.ACCT_TYPE = #{accountType}


    	and PTL.CCY = #{ccy,jdbcType=VARCHAR}

mapper.select:
select count(*) from 
	PTL_CASH_POSITION_FLOW A
	inner join PTL_CASH_POSITION D
	on A.PORTFOLIO_ID = D.PORTFOLIO_ID
	and A.CCY = D.CCY
	and A.CDATE = D.CDATE
	and A.HODING_TYPE = D.HODING_TYPE
	and A.ACCT_ID = D.ACCT_ID
	inner join PTL_PORTFOLIO C
	on A.PORTFOLIO_ID = C.PORTFOLIO_ID
where A.PORTFOLIO_ID = #{portfolioId}
	and A.CCY = #{ccy}
	and A.CDATE = #{cdate}
	and A.HODING_TYPE = #{hodingType}
	and A.ACCT_ID = #{acctId}

select * from (with temp as ( select A.*,'02' isSummary from (
select * from ( SELECT DISTINCT A.CDATE CDATE, A.PORTFOLIO_ID PORTFOLIOID, A.CCY CCY, B.TRADE_ID BUSINO,
case when A.AMOUNT >=0 then NVL(C.Trade_Amt*1,A.AMOUNT) else NVL(C.Trade_Amt*-1,A.AMOUNT) end as AMOUNT,
F.PORTFOLIO_NAME PORTFOLIONAME, nvl(D.FINPROD_MARKET_ID,D1.FINPROD_MARKET_ID) FINPRODMARKETID, nvl(D.FINPROD_ABBR,D1.FINPROD_ABBR) FINPRODABBR, /*DECODE(PA.PA_BUSS_TYPE, NULL, TOTAL.PA_BUSS_TYPE, PA.PA_BUSS_TYPE) BUSITYPE*/ NVL(SYS1.ITEM_VALUE,SYS3.ITEM_VALUE) BUSITYPE,
NVL(SYS5.ITEM_VALUE,NVL(SYS2.ITEM_VALUE,SYS4.ITEM_VALUE)) ps FROM PTL_CASH_POSITION_FLOW A LEFT JOIN ( select orders.ORDER_ID,rfpd.TRADE_ID from STL_PAY_ORDERS orders left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on orders.TRADE_ID = tfpdt.TOTLE_TRADE_ID left join TRDQUTO_MATCH_INFO tmi on tfpdt.TOTLE_TRADE_ID = tmi.TRD_ID left join REG_FIN_PRODUCT_DEAL_TOTAL rfpdt on tmi.PRE_TRADE_ID = rfpdt.TOTLE_TRADE_ID left join REG_FIN_PRODUCT_DEAL rfpd on rfpdt.TOTLE_TRADE_ID = rfpd.TOTLE_TRADE_ID UNION ALL select orders.ORDER_ID,tpd.TRADE_ID from STL_PAY_ORDERS orders left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on orders.TRADE_ID = tfpdt.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TOTLE_TRADE_ID = tfpdt.TOTLE_TRADE_ID ) orders ON orders.TRADE_ID = A.ORDER_ID INNER JOIN STL_PAY_ORDERS B ON
(B.ORDER_ID = A.ORDER_ID OR orders.ORDER_ID = B.ORDER_ID) LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TTOTAL ON B.TRADE_ID = TTOTAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL C
ON ( C.FINPROD_TYPE2 IN ('F02','F03','F04','F05','F08','F09') AND B.TRADE_ID = C.TRADE_ID )
or( C.FINPROD_TYPE2 in ('C11','C20') AND (B.TRADE_ID = nvl(C.TOTLE_TRADE_ID,C.TRADE_ID)) and C.FINPROD_ID = 'F16_'||B.PORTFOLIO_ID ) OR ( C.FINPROD_TYPE2 NOT IN ('F02','F03','F04','F05','F08','F09','C11','C20') AND (B.TRADE_ID = nvl(C.TOTLE_TRADE_ID,C.TRADE_ID) OR B.TRADE_ID = C.TRADE_ID ) )
OR (C.FINPROD_TYPE2 IS NULL AND B.TRADE_ID = C.TRADE_ID ) OR (TTOTAL.P_TRADE_ID is not null and C.TOTLE_TRADE_ID = TTOTAL.P_TRADE_ID and C.TRADE_STATUS='03') LEFT JOIN PA_TRD_PRODUCT_DEAL PA
ON ( C.FINPROD_TYPE2 IN ('F02','F03','F04','F05','F08','F09') AND PA.TRADE_ID = C.TRADE_ID ) OR ( C.FINPROD_TYPE2 NOT IN ('F02','F03','F04','F05','F08','F09') AND ( PA.TRADE_ID = nvl(C.TOTLE_TRADE_ID,C.TRADE_ID) OR PA.TRADE_ID = C.TRADE_ID ) ) OR ( C.FINPROD_TYPE2 IS NULL AND PA.TRADE_ID = C.TRADE_ID ) LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON TOTAL.TOTLE_TRADE_ID = B.TRADE_ID LEFT JOIN FIN_PRODUCT D ON C.FINPROD_ID = D.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE E ON D.FINPROD_ID = E.FINPROD_ID INNER JOIN PTL_PORTFOLIO F ON A.PORTFOLIO_ID = F.PORTFOLIO_ID LEFT JOIN sys_datadict_list SYS1 on C.FINPROD_TYPE2 = SYS1.item_code and SYS1.dict_code = 'FINPROD_TYPE_TG' LEFT JOIN sys_datadict_list SYS2 on C.PS = SYS2.item_code and SYS2.dict_code = 'PS' LEFT JOIN FIN_PRODUCT D1 ON TTOTAL.FINPROD_ID = D1.FINPROD_ID LEFT JOIN sys_datadict_list SYS3 ON TTOTAL.FINPROD_TYPE2 = SYS3.item_code AND SYS3.dict_code = 'FINPROD_TYPE_TG' LEFT JOIN sys_datadict_list SYS4 ON TTOTAL.PS = SYS4.item_code AND SYS4.dict_code = 'PS' left join sys_datadict_list SYS5 on PA.BACK_LEND_DIRECTION = SYS5.ITEM_CODE and SYS5.DICT_CODE = 'BACK_LEND_DIRECTION' WHERE 1 = 1
and A.PORTFOLIO_ID = #{portfolioId}
and A.CCY = #{ccy}
and A.CDATE = #{cdate}
and A.HODING_TYPE = #{hodingType}
and A.ACCT_ID = #{acctId}
AND NVL(C.FINPROD_TYPE2,TTOTAL.FINPROD_TYPE2) = #{busiType}
AND NVL(PA.BACK_LEND_DIRECTION,NVL(C.PS,TTOTAL.PS)) = #{ps}
) UNION ALL SELECT DISTINCT A.CDATE CDATE, A.PORTFOLIO_ID PORTFOLIOID, A.CCY CCY, T.TRADE_ID BUSINO, A.AMOUNT AMOUNT, PP.PORTFOLIO_NAME PORTFOLIONAME, null FINPRODMARKETID, null FINPRODABBR, /*pa.PA_BUSS_TYPE BUSITYPE*/ SYS1.ITEM_VALUE BUSITYPE, NVL(SYS3.ITEM_VALUE,SYS2.ITEM_VALUE) ps FROM PTL_CASH_POSITION_FLOW A INNER JOIN stl_dvp_orders B ON B.ORDER_ID = A.ORDER_ID LEFT JOIN STL_DVP_TRADE_MATCH SDTM ON B.ORDER_ID = SDTM.ORDER_ID LEFT JOIN TRD_PRODUCT_DEAL T ON T.TRADE_ID = SDTM.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL PA on t.trade_id = pa.trade_id LEFT JOIN PTL_TRADE PT ON T.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON A.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN sys_datadict_list SYS1 on T.FINPROD_TYPE2 = SYS1.item_code and SYS1.dict_code = 'FINPROD_TYPE_TG' LEFT JOIN sys_datadict_list SYS2 on T.PS = SYS2.item_code and SYS2.dict_code = 'PS' left join sys_datadict_list SYS3 on PA.BACK_LEND_DIRECTION = SYS3.ITEM_CODE and SYS3.DICT_CODE = 'BACK_LEND_DIRECTION' WHERE 1 = 1 AND B.ORDER_STATUS!='02'
and A.PORTFOLIO_ID = #{portfolioId}
and A.CCY = #{ccy}
and A.CDATE = #{cdate}
and A.HODING_TYPE = #{hodingType}
and A.ACCT_ID = #{acctId}
AND T.FINPROD_TYPE2 = #{busiType}
AND NVL(PA.BACK_LEND_DIRECTION,T.PS) = #{ps}
)A ) select * from temp
union select null CDATE, '' PORTFOLIOID, '' CCY, '' BUSINO, decode(sum(AMOUNT),null,0,sum(AMOUNT)) AMOUNT, '' PORTFOLIONAME, '' FINPRODMARKETID, '' FINPRODABBR, '' BUSITYPE, '' ps, '01' isSummary from temp)

select DISTINCT A.CDATE cdate, A.PORTFOLIO_ID || A.CCY || A.CDATE || A.HODING_TYPE || A.ACCT_ID portfolioId, A.PORTFOLIO_ID portfolioId1, A.ACCT_ID acctId, A.CCY ccy, A.HODING_TYPE hodingType, A.AMOUNT amount, D.amount1 amount1, '' portfolioName, '' bankDep, '' acctName, '' largePayno, '' swiftCode, 'root' AS upperPortfolioCode, '01' as hasChildren from PTL_CASH_POSITION A
inner join PTL_PORTFOLIO C on A.PORTFOLIO_ID = C.PORTFOLIO_ID left join ( select a.PORTFOLIO_ID,a.ACCT_ID,a.CDATE,a.CCY,a.HODING_TYPE,sum(a.AMOUNT) amount1 from Ptl_cash_Position_Flow a group by a.PORTFOLIO_ID,a.ACCT_ID,a.CDATE,a.CCY,a.HODING_TYPE ) D on A.PORTFOLIO_ID=D.PORTFOLIO_ID and A.ACCT_ID=D.ACCT_ID and A.CDATE=D.CDATE and A.CCY=D.CCY and A.HODING_TYPE = D.HODING_TYPE
and A.PORTFOLIO_ID = #{portfolioId}
and A.CDATE >= #{startCdate}
and A.CDATE <= #{endCdate}
union all select DISTINCT A.CDATE cdate, A.PORTFOLIO_ID portfolioId, A.PORTFOLIO_ID portfolioId1, A.ACCT_ID acctId, A.CCY ccy, A.HODING_TYPE hodingType, D.AMOUNT amount, A.AMOUNT amount1, C.PORTFOLIO_NAME portfolioName, B.BANK_DEP bankDep, B.ACCT_NAME acctName, B.LARGE_PAYNO largePayno, B.SWIFT_CODE swiftCode, D.PORTFOLIO_ID || D.CCY || D.CDATE || D.HODING_TYPE || D.ACCT_ID AS upperPortfolioCode, '02' as hasChildren from PTL_CASH_POSITION_FLOW A inner join PTL_CASH_POSITION D on A.PORTFOLIO_ID = D.PORTFOLIO_ID and A.CCY = D.CCY and A.CDATE = D.CDATE and A.HODING_TYPE = D.HODING_TYPE and A.ACCT_ID = D.ACCT_ID inner join STL_CAPACCT_INFO B on D.ACCT_ID = B.ACCT_NO inner join PTL_PORTFOLIO C on A.PORTFOLIO_ID = C.PORTFOLIO_ID
and A.PORTFOLIO_ID = #{portfolioId}
and A.CDATE >= #{startCdate}
and A.CDATE <= #{endCdate}
